import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CAfGEm1x.js";const u=JSON.parse('{"title":"Safety and selection","description":"","frontmatter":{},"headers":[],"relativePath":"safety.md","filePath":"safety.md"}'),i={name:"safety.md"};function n(d,e,l,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="safety-and-selection" tabindex="-1">Safety and selection <a class="header-anchor" href="#safety-and-selection" aria-label="Permalink to &quot;Safety and selection&quot;">​</a></h1><p>Every optimisation probes its scope and prints a plan. Selected targets are checked again before action; results are reported and recorded locally.</p><h2 id="read-the-safety-tier" tabindex="-1">Read the safety tier <a class="header-anchor" href="#read-the-safety-tier" aria-label="Permalink to &quot;Read the safety tier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Meaning</th><th>Selection</th></tr></thead><tbody><tr><td>Safe</td><td>Eligible for safe suggestions after live checks</td><td><code>y</code>, displayed numbers, or <code>-f</code> when force-eligible</td></tr><tr><td>Review</td><td>Requires you to review the exact target and action</td><td>Displayed numbers only</td></tr><tr><td>Protected</td><td>Inventory only</td><td>Cannot be selected</td></tr></tbody></table><ul><li>A blank answer cancels the run.</li><li><code>-f, --force</code> skips the prompt and applies only safe, force-eligible targets. It is available on <code>all</code>, <code>storage</code>, <code>projects</code>, and <code>repos</code>.</li><li>Without an interactive terminal and without <code>-f</code>, the plan is printed and the run cancels.</li><li>Cleanup can require dependencies or caches to be downloaded or rebuilt later. Review the plan&#39;s action as well as its path.</li></ul><p>There is no public <code>--dry-run</code> flag. To inspect a plan interactively, run without <code>-f</code> and leave the selection blank.</p><h2 id="understand-beta-opt-in" tabindex="-1">Understand beta opt-in <a class="header-anchor" href="#understand-beta-opt-in" aria-label="Permalink to &quot;Understand beta opt-in&quot;">​</a></h2><p>Delivery status and safety tier are separate: a published rule can still require review or be protected. <code>--allow-beta</code> attempts only beta rules with code-approved handlers and readiness checks.</p><p>Current executable beta handlers cover:</p><ul><li>Yarn Classic 1.x cache review from a selected package workspace.</li><li>Python virtual environments and tox/Nox test environments on Linux, requiring numbered selection.</li><li>Protected Docker network and volume inventories, which cannot be removed.</li></ul><p>Other beta entries remain catalogue-only and are reported as unavailable. Opting in never makes review or protected targets force-eligible. See the <a href="./reference/rules.html">rule catalogue</a> for delivery status.</p><h2 id="know-the-limits" tabindex="-1">Know the limits <a class="header-anchor" href="#know-the-limits" aria-label="Permalink to &quot;Know the limits&quot;">​</a></h2><ul><li>Project discovery is limited to depth 7 and does not traverse symlinks or generated/protected directories.</li><li>Generated targets must pass marker, identity, ownership, and activity checks. Recent activity or incomplete checks can exclude a target.</li><li>The seven-day no-change check cannot prove that no process still has an old file open. Stop relevant builds and tools before selecting cleanup.</li><li>Generated-path deletion requires the system Python helper and supported descriptor operations; missing support prevents deletion.</li><li>No undo archive is created. Keep anything you need before selecting its removal.</li></ul><h2 id="find-the-audit" tabindex="-1">Find the audit <a class="header-anchor" href="#find-the-audit" aria-label="Permalink to &quot;Find the audit&quot;">​</a></h2><ul><li>SQLite action records: <code>~/.kundol/kundol.db</code>.</li><li>Per-process text logs: <code>~/.kundol/sessions/session-&lt;timestamp&gt;-&lt;pid&gt;.log</code>.</li></ul><p>Session text logs are best effort. An audit warning after an action does not mean the action was rolled back; check the printed outcome before retrying. Read <a href="./troubleshooting.html">troubleshooting</a> for common results.</p>',16)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
